// Demo: Fix Validation Runner - Signature build-tool concept
(function(){'use strict';
var DATA={"label": "Fix Validation Runner - Signature build-tool concept", "arr": [21, 58, 74, 122, 123, 126, 128, 132, 174, 196], "target": 174};

